import numpy as np, math
from rdkit import Chem
from rdkit.Chem import AllChem

def make_fragment(smiles, seed, force='mmff'):
    m=Chem.MolFromSmiles(smiles); nheavy=m.GetNumAtoms(); m=Chem.AddHs(m)
    prm=AllChem.ETKDGv3(); prm.randomSeed=seed; prm.maxIterations=1000; prm.useSmallRingTorsions=True
    if AllChem.EmbedMolecule(m,prm)!=0: raise RuntimeError('embed')
    if force=='mmff' and AllChem.MMFFHasAllMoleculeParams(m):
        pp=AllChem.MMFFGetMoleculeProperties(m); ff=AllChem.MMFFGetMoleculeForceField(m,pp)
    else: ff=AllChem.UFFGetMoleculeForceField(m)
    ff.Minimize(maxIts=800)
    return m,np.array(m.GetConformer().GetPositions()),[a.GetSymbol() for a in m.GetAtoms()]
def u(v): return np.asarray(v,float)/np.linalg.norm(v)
def rotmat_axis_alignment(m,xyz,pidx,b,phi):
    nbr=[a.GetIdx() for a in m.GetAtomWithIdx(pidx).GetNeighbors() if a.GetSymbol()!='H']
    lp=-sum(u(xyz[j]-xyz[pidx]) for j in nbr); a=u(lp); b=u(b)
    r=np.array([1.,0,0]);
    if abs(a@r)>.85:r=np.array([0.,1,0])
    q=u(r-(r@a)*a); w=np.cross(a,q)
    r2=np.array([0.,0,1.]);
    if abs(b@r2)>.85:r2=np.array([0.,1.,0.])
    q0=u(r2-(r2@b)*b); w0=np.cross(b,q0)
    q1=np.cos(phi)*q0+np.sin(phi)*w0; w1=-np.sin(phi)*q0+np.cos(phi)*w0
    return np.column_stack([b,q1,w1])@np.column_stack([a,q,w]).T

def dock(m,xyz,pidx,pos,axis,phi):
    R=rotmat_axis_alignment(m,xyz,pidx,axis,phi)
    return (xyz-xyz[pidx])@R.T+pos

def matrices(ea,eb):
    limits=np.empty((len(ea),len(eb)))
    for i,a in enumerate(ea):
      for j,b in enumerate(eb):
        limits[i,j]=1.75 if a=='H' and b=='H' else (2.25 if a=='H' or b=='H' else 3.05)
    return limits

def score(A,ea,B,eb):
    ds=np.linalg.norm(A[:,None,:]-B[None,:,:],axis=2)
    lim=matrices(ea,eb)
    return float(np.maximum(lim-ds,0).dot(np.maximum(lim-ds,0).T).trace()) # sum squares
# simpler/vectorized sum of squared overlaps
def score(A,ea,B,eb):
    ds=np.linalg.norm(A[:,None,:]-B[None,:,:],axis=2)
    lim=matrices(ea,eb)
    return float(np.square(np.maximum(lim-ds,0)).sum())

def min_dist(A,B): return np.min(np.linalg.norm(A[:,None,:]-B[None,:,:],axis=2))

phis=np.linspace(0,2*np.pi,36,endpoint=False)
# conformational pools
bots=[]; p3s=[]; tops=[]
for k in range(12): bots.append(make_fragment('P(c1ccccc1)(c1ccccc1)c1ccccc1',101+k,'mmff'))
for k in range(16): p3s.append(make_fragment('P(c1ccccc1)(c1ccccc1)c1ccccc1',301+k,'mmff'))
for k in range(16): tops.append(make_fragment('P(c1ccccc1)(c1ccccc1)c1ccccc1[Sn](C)C',501+k,'uff'))

# Generate positioned chelate conformers and associated Ru donor directions.
chels=[]
for bm,bxyz,be in bots:
    P=0; donor=18; p=bxyz[P]; c=bxyz[donor]; dv=c-p; d=np.linalg.norm(dv); uv=dv/d
    normal=u(np.cross(bxyz[14]-bxyz[13],bxyz[18]-bxyz[13])); perp=u(np.cross(normal,uv))
    rp,rc=2.35,2.05; xx=(rp*rp-rc*rc+d*d)/(2*d); yy2=rp*rp-xx*xx
    if yy2<=0: continue
    yy=np.sqrt(yy2); opts=[p+xx*uv+yy*perp,p+xx*uv-yy*perp]
    rloc=max(opts,key=lambda r:min(np.linalg.norm(r-bxyz[j]) for j in [13,14,15,16,17]))
    hdon=[a.GetIdx() for a in bm.GetAtomWithIdx(donor).GetNeighbors() if a.GetSymbol()=='H'][0]
    e1=u(p-rloc); vc=c-rloc; alpha=np.arccos(np.clip(np.dot(e1,u(vc)),-1,1)); e2=u(u(vc)-np.dot(u(vc),e1)*e1); e3=u(np.cross(e1,e2))
    g1=np.array([0.,-1.,0.]); g2=np.array([np.sin(alpha),-np.cos(alpha),0.]); g3=u(np.cross(g1,g2))
    R=np.column_stack([g1,g2,g3])@np.column_stack([e1,e2,e3]).T
    bx=(bxyz-rloc)@R.T
    # c donor vector at the metal and remaining tetrahedrally-inspired positions
    vp=u(bx[P]); vcg=u(bx[donor]); ang=np.arccos(np.clip(vp@vcg,-1,1))
    mvec=u(vp+vcg); aa=1/(3*np.cos(ang/2)); bb=np.sqrt(max(1-aa*aa,0))
    v3=u(-aa*mvec+bb*np.array([0.,0.,1.])); v4=u(-aa*mvec-bb*np.array([0.,0.,1.]))
    elems=be
    chels.append((bm,bx,elems,hdon,v3,v4,ang))

best=None
for ci,(bm,bx,be,hdon,v3,v4,ang) in enumerate(chels):
    # select lowest-clash configurations of PPh3 for this chelate
    p3_opts=[]
    for pm,px,pe in p3s:
        vals=[]
        pos=2.35*v3
        for phi in phis:
            z=dock(pm,px,0,pos,-v3,phi)
            vals.append((score(bx,be,z,pe),z,pm,pe,phi))
