        for phi2 in phis:
          z2=dock(tm,tx,0,pos,-v4,phi2)
          s2=score(bx,be,z2,te)+score(z1,pe,z2,te)
          total=s1+s2
          if best is None or total<best[0]:
            best=(total,ci,bx,be,hdon,v3,v4,pm,z1,pe,phi1,tm,z2,te,phi2,ang)

print('best score',best[0],'chelate conformer',best[1],'phi',best[10],best[14],'bite',np.degrees(best[15]))
_,ci,bx,be,hdon,v3,v4,pm,z1,pe,phi1,tm,z2,te,phi2,ang=best
for name,A,ea,B,eb in [('chel/PPh3',bx,be,z1,pe),('chel/top',bx,be,z2,te),('PPh3/top',z1,pe,z2,te)]:print(name,'minimum distance',min_dist(A,B))
