 ds=np.linalg.norm(A[:,None,:]-B[None,:,:],axis=2)
 ix=np.unravel_index(np.argmin(ds),ds.shape)
 print(name,'closest atoms',ix,ea[ix[0]],eb[ix[1]],ds[ix])
# save xyz, omit explicit ortho-H; append two mono ligands
coords=[]; els=[]
for xyz,elems,skip in [(bx,be,{hdon}),(z1,pe,set()),(z2,te,set())]:
 for i,(q,e) in enumerate(zip(xyz,elems)):
  if i not in skip: coords.append(q); els.append(e)
coords.append(np.zeros(3)); els.append('Ru')
